CREATE TABLE public.webhook_endpoints (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, integration_id uuid NOT NULL, environment public.environment NOT NULL, url text NOT NULL CHECK (length(url)<=2048 AND url ~ '^https://'), description text NOT NULL DEFAULT '' CHECK(length(description)<=2000), events text[] NOT NULL CHECK(cardinality(events)>0), active boolean NOT NULL DEFAULT true, disabled_reason text, secret jsonb, secret_prefix text NOT NULL, previous_secret jsonb, previous_secret_expires_at timestamptz, created_by uuid NOT NULL REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), last_success_at timestamptz, failing_since timestamptz, deleted_at timestamptz, UNIQUE(id,organization_id,integration_id,environment), FOREIGN KEY(integration_id,organization_id) REFERENCES public.integrations(id,organization_id), CHECK(deleted_at IS NULL OR (NOT active AND secret IS NULL AND previous_secret IS NULL)));
REVOKE ALL ON public.webhook_endpoints FROM PUBLIC, anon, authenticated;
GRANT SELECT(id,organization_id,integration_id,environment,url,description,events,active,disabled_reason,secret_prefix,previous_secret_expires_at,created_by,created_at,updated_at,last_success_at,failing_since,deleted_at) ON public.webhook_endpoints TO authenticated;
GRANT ALL ON public.webhook_endpoints TO service_role;
ALTER TABLE public.webhook_endpoints ENABLE ROW LEVEL SECURITY;
CREATE POLICY webhook_endpoint_read ON public.webhook_endpoints FOR SELECT TO authenticated USING (public.is_org_member(organization_id) OR public.is_platform_admin());
CREATE TABLE public.webhook_events (id text PRIMARY KEY CHECK(id ~ '^evt_[a-f0-9]{32}$'), organization_id uuid NOT NULL, integration_id uuid NOT NULL, environment public.environment NOT NULL, type text NOT NULL, payload jsonb NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(id,organization_id,integration_id,environment), FOREIGN KEY(integration_id,organization_id) REFERENCES public.integrations(id,organization_id));
REVOKE ALL ON public.webhook_events FROM PUBLIC,anon,authenticated; GRANT SELECT ON public.webhook_events TO authenticated; GRANT ALL ON public.webhook_events TO service_role;
ALTER TABLE public.webhook_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY webhook_event_read ON public.webhook_events FOR SELECT TO authenticated USING(public.is_org_member(organization_id) OR public.is_platform_admin());
CREATE TABLE public.webhook_deliveries (id text PRIMARY KEY CHECK(id ~ '^whd_[a-f0-9]{32}$'), event_id text NOT NULL, endpoint_id uuid NOT NULL, organization_id uuid NOT NULL, integration_id uuid NOT NULL, environment public.environment NOT NULL, cycle integer NOT NULL DEFAULT 0 CHECK(cycle>=0), attempt integer NOT NULL CHECK(attempt BETWEEN 1 AND 8), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','succeeded','failed','exhausted')), next_attempt_at timestamptz NOT NULL DEFAULT now(), response_status integer, response_body text CHECK(octet_length(response_body)<=4096), duration_ms integer, error text, claim_token uuid, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(event_id,endpoint_id,cycle,attempt), FOREIGN KEY(event_id,organization_id,integration_id,environment) REFERENCES public.webhook_events(id,organization_id,integration_id,environment), FOREIGN KEY(endpoint_id,organization_id,integration_id,environment) REFERENCES public.webhook_endpoints(id,organization_id,integration_id,environment));
REVOKE ALL ON public.webhook_deliveries FROM PUBLIC,anon,authenticated; GRANT SELECT ON public.webhook_deliveries TO authenticated; GRANT ALL ON public.webhook_deliveries TO service_role;
ALTER TABLE public.webhook_deliveries ENABLE ROW LEVEL SECURITY;
CREATE POLICY webhook_delivery_read ON public.webhook_deliveries FOR SELECT TO authenticated USING(public.is_org_member(organization_id) OR public.is_platform_admin());
CREATE TABLE public.webhook_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL, integration_id uuid NOT NULL, environment public.environment NOT NULL, endpoint_id uuid NOT NULL, episode_at timestamptz NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(endpoint_id,episode_at), FOREIGN KEY(endpoint_id,organization_id,integration_id,environment) REFERENCES public.webhook_endpoints(id,organization_id,integration_id,environment));
REVOKE ALL ON public.webhook_alerts FROM PUBLIC,anon,authenticated; GRANT SELECT ON public.webhook_alerts TO authenticated; GRANT ALL ON public.webhook_alerts TO service_role;
ALTER TABLE public.webhook_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY webhook_alert_read ON public.webhook_alerts FOR SELECT TO authenticated USING(public.is_org_member(organization_id) OR public.is_platform_admin());
CREATE INDEX webhook_delivery_due ON public.webhook_deliveries(next_attempt_at) WHERE status='pending';
CREATE INDEX webhook_delivery_history ON public.webhook_deliveries(organization_id,integration_id,environment,created_at DESC);
CREATE INDEX webhook_endpoint_failing ON public.webhook_endpoints(failing_since) WHERE active AND deleted_at IS NULL;
CREATE INDEX webhook_event_retention ON public.webhook_events(created_at);
CREATE INDEX webhook_alert_retention ON public.webhook_alerts(created_at);
CREATE OR REPLACE FUNCTION public.guard_webhook_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF ROW(NEW.organization_id,NEW.integration_id,NEW.environment,NEW.id) IS DISTINCT FROM ROW(OLD.organization_id,OLD.integration_id,OLD.environment,OLD.id) THEN RAISE EXCEPTION 'Webhook identity is immutable'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_webhook_identity() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.guard_webhook_identity() TO service_role;
CREATE TRIGGER webhook_endpoint_guard BEFORE UPDATE ON public.webhook_endpoints FOR EACH ROW EXECUTE FUNCTION public.guard_webhook_identity();
CREATE TRIGGER webhook_delivery_guard BEFORE UPDATE ON public.webhook_deliveries FOR EACH ROW EXECUTE FUNCTION public.guard_webhook_identity();
CREATE OR REPLACE FUNCTION public.manage_webhook(_actor uuid,_org uuid,_integration uuid,_action text,_id uuid,_payload jsonb) RETURNS uuid LANGUAGE plpgsql SET search_path=public AS $$ DECLARE e public.webhook_endpoints; roles_ok boolean; BEGIN
SELECT EXISTS(SELECT 1 FROM public.platform_admins WHERE user_id=_actor) OR EXISTS(SELECT 1 FROM public.organization_members WHERE user_id=_actor AND organization_id=_org AND role IN ('owner','admin','developer')) INTO roles_ok;
IF NOT roles_ok THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF;
PERFORM 1 FROM public.integrations WHERE id=_integration AND organization_id=_org FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Integração inválida'; END IF;
IF _action='create' THEN
INSERT INTO public.webhook_endpoints(id,organization_id,integration_id,environment,url,description,events,secret,secret_prefix,created_by) VALUES(_id,_org,_integration,(_payload->>'environment')::public.environment,_payload->>'url',COALESCE(_payload->>'description',''),ARRAY(SELECT jsonb_array_elements_text(_payload->'events')),_payload->'secret',_payload->>'secret_prefix',_actor) RETURNING * INTO e;
ELSE SELECT * INTO e FROM public.webhook_endpoints WHERE id=_id AND organization_id=_org AND integration_id=_integration AND deleted_at IS NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Endereço não encontrado'; END IF;
IF _action='save' THEN UPDATE public.webhook_endpoints SET url=_payload->>'url',description=COALESCE(_payload->>'description',''),events=ARRAY(SELECT jsonb_array_elements_text(_payload->'events')) WHERE id=e.id;
ELSIF _action='rotate' THEN UPDATE public.webhook_endpoints SET previous_secret=secret,previous_secret_expires_at=now()+interval '24 hours',secret=_payload->'secret',secret_prefix=_payload->>'secret_prefix' WHERE id=e.id;
ELSIF _action='active' THEN UPDATE public.webhook_endpoints SET active=(_payload->>'active')::boolean,disabled_reason=NULL,failing_since=CASE WHEN (_payload->>'active')::boolean THEN NULL ELSE failing_since END WHERE id=e.id;
ELSIF _action='delete' THEN UPDATE public.webhook_endpoints SET active=false,deleted_at=now(),secret=NULL,previous_secret=NULL,previous_secret_expires_at=NULL,disabled_reason='Excluído pelo responsável' WHERE id=e.id; UPDATE public.webhook_deliveries SET status='exhausted',error='ENDERECO_EXCLUIDO',claim_token=NULL,lease_until=NULL WHERE endpoint_id=e.id AND status='pending';
ELSE RAISE EXCEPTION 'Ação inválida'; END IF; END IF; RETURN _id; END $$;
REVOKE ALL ON FUNCTION public.manage_webhook(uuid,uuid,uuid,text,uuid,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.manage_webhook(uuid,uuid,uuid,text,uuid,jsonb) TO service_role;
CREATE OR REPLACE FUNCTION public.emit_webhook_event(_id text,_org uuid,_integration uuid,_environment public.environment,_type text,_body text,_endpoint uuid DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE n integer; BEGIN
PERFORM 1 FROM public.integrations WHERE id=_integration AND organization_id=_org AND active FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Integração inativa'; END IF;
IF _body::jsonb->>'id' IS DISTINCT FROM _id OR _body::jsonb->>'organizacao_id' IS DISTINCT FROM _org::text OR _body::jsonb->>'integracao_id' IS DISTINCT FROM _integration::text OR _body::jsonb->>'tipo' IS DISTINCT FROM _type OR _body::jsonb->>'ambiente' IS DISTINCT FROM (CASE WHEN _environment='sandbox' THEN 'homologacao' ELSE 'producao' END) THEN RAISE EXCEPTION 'Evento inválido'; END IF;
INSERT INTO public.webhook_events(id,organization_id,integration_id,environment,type,payload,body) VALUES(_id,_org,_integration,_environment,_type,_body::jsonb,_body);
INSERT INTO public.webhook_deliveries(id,event_id,endpoint_id,organization_id,integration_id,environment,attempt) SELECT 'whd_'||replace(gen_random_uuid()::text,'-',''),_id,id,_org,_integration,_environment,1 FROM public.webhook_endpoints WHERE organization_id=_org AND integration_id=_integration AND environment=_environment AND active AND deleted_at IS NULL AND (_endpoint IS NULL OR id=_endpoint) AND (_type=ANY(events) OR _type='webhook.teste'); GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.emit_webhook_event(text,uuid,uuid,public.environment,text,text,uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.emit_webhook_event(text,uuid,uuid,public.environment,text,text,uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.claim_webhook_deliveries(_event text DEFAULT NULL,_limit integer DEFAULT 10) RETURNS SETOF public.webhook_deliveries LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
RETURN QUERY WITH picked AS (SELECT d.id FROM public.webhook_deliveries d JOIN public.webhook_endpoints e ON e.id=d.endpoint_id JOIN public.integrations i ON i.id=d.integration_id WHERE d.status='pending' AND d.next_attempt_at<=now() AND (d.lease_until IS NULL OR d.lease_until<now()) AND e.active AND e.deleted_at IS NULL AND i.active AND (_event IS NULL OR d.event_id=_event) ORDER BY d.next_attempt_at LIMIT LEAST(GREATEST(_limit,1),10) FOR UPDATE OF d SKIP LOCKED) UPDATE public.webhook_deliveries d SET claim_token=gen_random_uuid(),lease_until=now()+interval '2 minutes' FROM picked WHERE d.id=picked.id RETURNING d.*; END $$;
REVOKE ALL ON FUNCTION public.claim_webhook_deliveries(text,integer) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.claim_webhook_deliveries(text,integer) TO service_role;
CREATE OR REPLACE FUNCTION public.finish_webhook_delivery(_id text,_token uuid,_http integer,_response text,_duration integer,_error text) RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$ DECLARE d public.webhook_deliveries; e public.webhook_endpoints; delay_s integer; success boolean; BEGIN
SELECT * INTO d FROM public.webhook_deliveries WHERE id=_id AND claim_token=_token AND status='pending' FOR UPDATE; IF NOT FOUND THEN RETURN false; END IF;
SELECT * INTO e FROM public.webhook_endpoints WHERE id=d.endpoint_id FOR UPDATE;
success=(_http BETWEEN 200 AND 299 AND _error IS NULL);
UPDATE public.webhook_deliveries SET status=CASE WHEN success THEN 'succeeded' WHEN attempt=8 THEN 'exhausted' ELSE 'failed' END,response_status=_http,response_body=_response,duration_ms=GREATEST(_duration,0),error=_error,claim_token=NULL,lease_until=NULL WHERE id=d.id;
IF e.deleted_at IS NOT NULL THEN RETURN true; END IF;
IF success THEN UPDATE public.webhook_endpoints SET last_success_at=now(),failing_since=NULL WHERE id=e.id;
ELSE UPDATE public.webhook_endpoints SET failing_since=COALESCE(failing_since,now()) WHERE id=e.id;
IF d.attempt<8 THEN delay_s=(ARRAY[60,300,1800,7200,21600,43200,86400])[d.attempt];
INSERT INTO public.webhook_deliveries(id,event_id,endpoint_id,organization_id,integration_id,environment,cycle,attempt,next_attempt_at) VALUES('whd_'||replace(gen_random_uuid()::text,'-',''),d.event_id,d.endpoint_id,d.organization_id,d.integration_id,d.environment,d.cycle,d.attempt+1,now()+make_interval(secs=>delay_s)) ON CONFLICT DO NOTHING; END IF; END IF; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.finish_webhook_delivery(text,uuid,integer,text,integer,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.finish_webhook_delivery(text,uuid,integer,text,integer,text) TO service_role;
CREATE OR REPLACE FUNCTION public.disable_failing_webhooks() RETURNS integer LANGUAGE plpgsql SET search_path=public AS $$ DECLARE n integer; BEGIN
WITH disabled AS (UPDATE public.webhook_endpoints SET active=false,disabled_reason='Falhas contínuas por 3 dias' WHERE active AND deleted_at IS NULL AND failing_since<=now()-interval '3 days' RETURNING *) INSERT INTO public.webhook_alerts(organization_id,integration_id,environment,endpoint_id,episode_at,message) SELECT organization_id,integration_id,environment,id,failing_since,'Endereço de webhook desativado após 3 dias de falhas contínuas.' FROM disabled ON CONFLICT DO NOTHING; GET DIAGNOSTICS n=ROW_COUNT;
UPDATE public.webhook_endpoints SET previous_secret=NULL,previous_secret_expires_at=NULL WHERE previous_secret_expires_at<=now(); RETURN n; END $$;
REVOKE ALL ON FUNCTION public.disable_failing_webhooks() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.disable_failing_webhooks() TO service_role;
CREATE OR REPLACE FUNCTION public.replay_webhook_delivery(_actor uuid,_org uuid,_id text) RETURNS text LANGUAGE plpgsql SET search_path=public AS $$ DECLARE d public.webhook_deliveries; c integer; newid text; BEGIN
IF NOT (EXISTS(SELECT 1 FROM public.platform_admins WHERE user_id=_actor) OR EXISTS(SELECT 1 FROM public.organization_members WHERE user_id=_actor AND organization_id=_org AND role IN ('owner','admin','developer'))) THEN RAISE EXCEPTION 'Acesso não autorizado'; END IF;
SELECT * INTO d FROM public.webhook_deliveries WHERE id=_id AND organization_id=_org AND status='exhausted' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Somente entrega esgotada pode ser reenviada'; END IF;
PERFORM 1 FROM public.webhook_endpoints e JOIN public.integrations i ON i.id=e.integration_id WHERE e.id=d.endpoint_id AND e.active AND e.deleted_at IS NULL AND i.active FOR UPDATE OF e; IF NOT FOUND THEN RAISE EXCEPTION 'Ative o endereço antes de reenviar'; END IF;
IF EXISTS(SELECT 1 FROM public.webhook_deliveries WHERE event_id=d.event_id AND endpoint_id=d.endpoint_id AND status='pending') THEN RAISE EXCEPTION 'Reenvio já pendente'; END IF;
SELECT COALESCE(max(cycle),0)+1 INTO c FROM public.webhook_deliveries WHERE event_id=d.event_id AND endpoint_id=d.endpoint_id; newid='whd_'||replace(gen_random_uuid()::text,'-',''); INSERT INTO public.webhook_deliveries(id,event_id,endpoint_id,organization_id,integration_id,environment,cycle,attempt) VALUES(newid,d.event_id,d.endpoint_id,d.organization_id,d.integration_id,d.environment,c,1); RETURN d.event_id; END $$;
REVOKE ALL ON FUNCTION public.replay_webhook_delivery(uuid,uuid,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.replay_webhook_delivery(uuid,uuid,text) TO service_role;
SELECT cron.alter_job(1, command := $$DELETE FROM public.webhook_alerts WHERE created_at < now()-interval '90 days'; DELETE FROM public.webhook_deliveries WHERE event_id IN (SELECT id FROM public.webhook_events WHERE created_at < now()-interval '90 days'); DELETE FROM public.webhook_events WHERE created_at < now()-interval '90 days'; DELETE FROM public.api_request_logs WHERE created_at < now()-interval '90 days';$$);